import { Kanban } from "march/ui"

// bir okuma panosu: kitabı sürükle (ya da odaklayıp Alt+→), okundu sütununa varınca tebrik satırı çıkar
type Book = { id: string; title: string }
type Col = { id: string; title: string; tone: string; items: Book[] }

export function ReadingBoard() {
  let $cols: Col[] = [
    { id: "next", title: "Okunacak", tone: "info", items: [{ id: "b1", title: "Dune" }, { id: "b2", title: "Kürk Mantolu Madonna" }] },
    { id: "now", title: "Okunuyor", tone: "warn", items: [{ id: "b3", title: "Simyacı" }] },
    { id: "done", title: "Okundu", tone: "success", items: [] },
  ]
  const move = (b: Book, from: string, to: string) => {
    $cols = $cols.map((c) => c.id === from ? { ...c, items: c.items.filter((x) => x.id !== b.id) } : c.id === to ? { ...c, items: [...c.items, b] } : c)
  }
  const read = () => $cols.find((c) => c.id === "done")!.items.length
  return <div sx={{ flex: "col", gap: 2 }}>
    <Kanban columns={() => $cols} onMove={move} />
    <p sx={{ text: "bold", color: "success" }}>{() => read() ? `Tebrikler: ${read()} kitap bitti 📚` : "Henüz bitmiş kitap yok"}</p>
  </div>
}

import { Kanban, Chip, Avatar, toast } from "march/ui"

// bir ekip panosu: her kartta iş, öncelik ve kişi; taşınınca bildirim çıkar, sayaç "n iş" yazar
type Task = { id: string; title: string; who: string; prio: "yüksek" | "orta" | "düşük" }
type Col = { id: string; title: string; tone: string; items: Task[] }
const PRIO = { "yüksek": "danger", "orta": "warn", "düşük": "neutral" } as const

// bir iş kartı: başlık, altında öncelik çipi ve kişinin baş harfleri
const TaskCard = (props: { task: Task }) => <div sx={{ flex: "col", gap: 1 }}>
  <strong>{props.task.title}</strong>
  <div sx={{ flex: ["row", "center"], gap: 2 }}>
    <Chip size="sm" tone={PRIO[props.task.prio]}>{props.task.prio}</Chip>
    <Avatar name={props.task.who} size="xs" />
  </div>
</div>

export function SprintBoard() {
  let $cols: Col[] = [
    { id: "todo", title: "Yapılacak", tone: "info", items: [{ id: "s1", title: "Giriş sayfası", who: "Ada Yılmaz", prio: "yüksek" }, { id: "s2", title: "E-posta şablonu", who: "Can Demir", prio: "düşük" }] },
    { id: "doing", title: "Sürüyor", tone: "warn", items: [{ id: "s3", title: "Ödeme hatası", who: "Ece Kaya", prio: "yüksek" }] },
    { id: "review", title: "İncelemede", tone: "primary", items: [] },
    { id: "done", title: "Bitti", tone: "success", items: [{ id: "s4", title: "Kayıt formu", who: "Ada Yılmaz", prio: "orta" }] },
  ]
  const move = (t: Task, from: string, to: string) => {
    $cols = $cols.map((c) => c.id === from ? { ...c, items: c.items.filter((x) => x.id !== t.id) } : c.id === to ? { ...c, items: [...c.items, t] } : c)
    toast(`“${t.title}” → ${$cols.find((c) => c.id === to)!.title}`)
  }
  return <Kanban columns={() => $cols} itemKey={(t: Task) => t.id} card={(t: Task) => <TaskCard task={t} />}
    count={(c: Col) => `${c.items.length} iş`} onMove={move} />
}

import { Kanban, Card } from "march/ui"
import { layers, star, Icon } from "march/icons"

// Kanban'ın bütün özellikleri bir arada: columns (tone ya da color), card, itemKey, onMove, dot (yok / kendi),
// count (yok / kendi), animate ve class; son hareket üstte yazılır
type Item = { key: string; name: string }
type Col = { id: string; title: string; tone?: string; color?: "brand-purple" | "brand-orange"; items: Item[] }

const start = (): Col[] => [
  { id: "a", title: "Fikir", tone: "info", items: [{ key: "i1", name: "Karanlık mod" }, { key: "i2", name: "Paylaşım" }] },
  { id: "b", title: "Tasarım", color: "brand-purple", items: [{ key: "i3", name: "Logo" }] },
  { id: "c", title: "Yayında", color: "brand-orange", items: [] },
]

// bir pano ve üstünde adı
const Box = (props: { title: string; children?: unknown }) => <div sx={{ flex: "col", gap: 1 }}>
  <span sx={{ text: "xs", color: "muted" }}>{props.title}</span>
  {props.children}
</div>

export function KanbanLab() {
  let $cols = start()
  let $last = "henüz yok"
  const move = (it: Item, from: string, to: string) => {
    $cols = $cols.map((c) => c.id === from ? { ...c, items: c.items.filter((x) => x.key !== it.key) } : c.id === to ? { ...c, items: [...c.items, it] } : c)
    $last = `${it.name}: ${from} → ${to}`
  }
  const card = (it: Item) => <span>{it.name}</span>
  const key = (it: Item) => it.key
  return <div sx={{ flex: "col", gap: 3 }}>
    <p>Son hareket: <b>{() => $last}</b></p>
    <Box title="Varsayılan: tonlu / renkli nokta, sayaç, giriş hareketi">
      <Kanban columns={() => $cols} card={card} itemKey={key} onMove={move} class="lab-board" />
    </Box>
    <Box title="Kendi noktam ve sayacım, hareketsiz">
      <Kanban columns={() => $cols} card={card} itemKey={key} onMove={move} animate={false}
        dot={(c: Col) => <Icon of={c.id === "c" ? star : layers} size="sm" />} count={(c: Col) => `${c.items.length} kart`} />
    </Box>
    <Card m:theme="night">
      <Box title="Noktasız, sayaçsız, koyu zemin">
        <Kanban columns={() => $cols} card={card} itemKey={key} onMove={move} dot={false} count={false} />
      </Box>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { KanbanLab } from "./KanbanLab.tsx"

// KanbanLab'in testleri: kaydedince Testler sekmesinde çalışır
test("her pano üç sütun; sütunlar başlıklarıyla adlanır", () => {
  const s = renderTest(() => <KanbanLab />)
  const board = s.get(".lab-board")!
  const cols = Array.from(board.querySelectorAll("section")) as Element[]
  expect(cols.map((c) => c.getAttribute("aria-label"))).toEqual(["Fikir", "Tasarım", "Yayında"])
})

test("itemKey kartın data-key'i olur; card içeriği yazar", () => {
  const s = renderTest(() => <KanbanLab />)
  const first = s.get(".lab-board .m-kanban-card")!
  expect(first.getAttribute("data-key")).toBe("i1")
  expect(first.textContent).toBe("Karanlık mod")
})

test("Alt+→ kartı bir sonraki sütuna taşır ve onMove çağrılır", async () => {
  const s = renderTest(() => <KanbanLab />)
  const card = s.get(".lab-board .m-kanban-card")!
  card.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", altKey: true, bubbles: true }))
  await s.flush()
  expect(s.sees("Son hareket: Karanlık mod: a → b")).toBe(true)
  expect(s.get(".lab-board section[data-col=b]")!.textContent).toContain("Karanlık mod")
})

test("count={false} ve dot={false} sayaç ile noktayı kaldırır; kendi sayacım yazılır", () => {
  const s = renderTest(() => <KanbanLab />)
  const boards = s.all(".m-kanban")
  expect(boards[1].querySelector(".m-kanban-count.is-own")?.textContent ?? "").toContain("kart")
  expect(boards[2].querySelector(".m-kanban-count")).toBe(null)
  expect(boards[2].querySelector(".m-kanban-dot")).toBe(null)
})
